/* Name Lock World 6, Stats and Research: six games and the Normal Curve Boss (app.js "stats world").
   Each question: o[0] is the right answer (the game shuffles the options), w[i] says why option i is right
   or wrong (and when a wrong one WOULD be right), r is the section of the stats book (notes/statistics/) that
   teaches it. Written 20 Nov 2026 from the real PYQs in take/ and the stats book, then fact-checked. */
window.NL_STATS = {name: "Stats and Research", icon: "📊", unit: "Stats and Research, six games and a boss",
  blurb: "Every Q is a short study. Pick the answer, then see why each option is right or wrong.",
  levels: [
  {k: "tp", name: "Test Picker", icon: "🧮", sub: "Read the study, pick the test. Twists: paired vs independent, parametric vs non-parametric", n: "which test to use", qs: [
    {"id": "tp-01", "q": "An IQ test has a population mean of 100 and a known population SD (σ) of 15. A psychologist tests 64 children from one Bangalore school to see whether their mean differs from the population mean. Which test fits?", "o": ["One-sample z test", "One-sample t test", "Independent-samples t test", "Chi-square goodness of fit"], "w": ["When σ is known, the standard error is exactly σ/√n, so z = (M − μ)/(σ/√n) is read off the normal curve (±1.96 at .05, two-tailed). One sample against a known population mean with σ given is the textbook z test.", "The one-sample t test of William Sealy Gosset (\"Student\") asks the same question when σ is unknown and must be estimated from the sample SD (s). Here σ is given, so z applies.", "The independent-samples t test compares two separate samples with each other. It would be right if this school's children were compared with children from another school, not with a known population value.", "Karl Pearson's chi-square goodness of fit compares observed frequencies across categories with expected ones. It would be right if children were counted into IQ bands (below average, average, above), not when a mean is tested."], "r": "s16"},
    {"id": "tp-02", "q": "At NIMHANS, 30 patients with social anxiety get group CBT and a different 30 stay on a waitlist. After 8 weeks both groups complete an anxiety scale (interval scores, roughly normal, similar variances). Do the two group means differ?", "o": ["Independent-samples t test", "Paired-samples t test", "Mann-Whitney U test", "Chi-square test of independence"], "w": ["Two separate groups of different people, one interval DV, normality and equal variances: the independent-samples t test of William Sealy Gosset (\"Student\"), with df = n₁ + n₂ − 2 = 58.", "The paired t test needs the same people measured twice, or matched pairs. It would be right if the same 30 patients were scored before and after CBT.", "The U test of Henry Mann and Donald Whitney is the rank-based alternative. It would be right if the anxiety scores were ordinal or badly skewed; with normal interval scores the t test keeps more power.", "Karl Pearson's chi-square test of independence works on frequencies of categories. It would be right if the outcome were counts such as improved versus not improved, not mean scores."], "r": "s9"},
    {"id": "tp-03", "q": "Twenty inpatients complete the Beck Depression Inventory on admission and again at discharge. Scores are interval and the admission-minus-discharge differences are roughly normal. Has the mean score changed?", "o": ["Paired-samples t test", "Independent-samples t test", "Pearson correlation (r)", "Wilcoxon signed-rank test"], "w": ["Same people measured twice gives related scores. The paired t of William Sealy Gosset (\"Student\") runs on each person's difference score, df = n − 1 = 19. Removing individual differences from the error term makes it more powerful than an independent t.", "The independent t treats the two sets of scores as coming from different people and leaves individual differences in the error term. It would be right if admission and discharge scores came from two separate groups of patients.", "Karl Pearson's r would show whether patients high on admission were also high at discharge (consistency), not whether the mean changed. It answers a relationship question, not a difference question.", "Frank Wilcoxon's signed-rank test is the non-parametric paired test. It would be right if the differences were badly skewed or the scale only ordinal; with normal interval differences the paired t is more powerful."], "r": "s16"},
    {"id": "tp-04", "q": "A Bangalore college compares statistics exam scores of three different groups of students taught by lecture, by video and by group discussion (25 students each). Scores are interval and normal with equal variances. Which test?", "o": ["One-way ANOVA", "Three separate independent t tests", "Kruskal-Wallis H test", "Repeated-measures ANOVA"], "w": ["Three or more independent groups, one IV, one interval DV: Ronald Fisher's one-way ANOVA. It tests all three means at once with F = MS between / MS within (df 2 and 72), keeping α at .05.", "Three t tests (lecture vs video, lecture vs discussion, video vs discussion) push the familywise Type I error to about .14 at α = .05. A t test is right only when there are exactly two groups.", "The H test of William Kruskal and W. Allen Wallis is the rank version for three or more independent groups. It would be right if scores were ordinal or badly skewed; here the parametric assumptions hold.", "Repeated-measures ANOVA is for the same people tested under every condition. It would be right if each student had been taught by all three methods in turn."], "r": "s10"},
    {"id": "tp-05", "q": "In a survey of 200 Bangalore college students, each student's gender (male, female) and preferred source of help for stress (counsellor, friend, family, no one) are recorded. Is help preference related to gender?", "o": ["Chi-square test of independence", "Chi-square goodness of fit", "McNemar test", "Independent-samples t test"], "w": ["Two nominal variables, each student counted once in a 2 × 4 table: Karl Pearson's chi-square test of independence, χ² = Σ(O − E)²/E with df = (2 − 1)(4 − 1) = 3.", "Goodness of fit, also from Karl Pearson, tests one nominal variable against expected proportions. It would be right if the only question were whether the four help sources are equally preferred, ignoring gender.", "Quinn McNemar's test is for the same people classified twice on a yes/no variable, such as before and after a programme. Here each student is classified once, on two different variables.", "The independent t compares two groups on an interval mean. Gender gives two groups, but help preference is a nominal category, not a score, so there is no mean to compare."], "r": "s14"},
    {"id": "tp-06", "q": "For 80 nursing students in Mysuru, a researcher records average nightly hours of sleep and score on a perceived stress scale. Both are interval, roughly normal, and the scatterplot looks linear. She wants the strength and direction of the relationship.", "o": ["Pearson r", "Spearman's ρ", "Point-biserial r", "Chi-square test of independence"], "w": ["Two continuous interval variables with a linear relationship: Karl Pearson's product-moment r, whose sign gives the direction and whose size (from −1 to +1) gives the strength.", "Charles Spearman's ρ correlates ranks. It would be right if the data were ranks or ordinal, or if outliers or a curved but monotonic pattern made Karl Pearson's r misleading.", "Point-biserial r is for one true dichotomy (such as male or female) paired with one continuous variable. Here both variables are continuous.", "Karl Pearson's chi-square tests association between two nominal variables using frequencies. It would be right only if sleep and stress had been cut into categories like low and high, which throws information away."], "r": "s12"},
    {"id": "tp-07", "q": "A pilot study compares days to relapse after discharge for 9 patients on Drug A and a different 9 patients on Drug B. A few patients stayed well for a very long time, so the data are strongly positively skewed. Which test?", "o": ["Mann-Whitney U test", "Independent-samples t test", "Wilcoxon signed-rank test", "Chi-square test of independence"], "w": ["Two independent groups, small and badly skewed samples: the U test of Henry Mann and Donald Whitney (1947) pools and ranks all scores and asks whether one group's ranks run systematically higher. Ranks blunt the extreme values.", "The independent t of William Sealy Gosset (\"Student\") assumes roughly normal populations; with 9 per group and heavy skew that is unsafe. It would be right if days to relapse were roughly normal.", "Frank Wilcoxon's signed-rank test is for two related samples (same people twice, or matched pairs). It would be right if the same patients had tried both drugs.", "Chi-square would be right if the outcome were a category, such as relapsed or not within six months. Here each patient has a count of days, which would be wasted by reducing it to frequencies."], "r": "s14"},
    {"id": "tp-08", "q": "Patients from three different wards (acute, rehabilitation, forensic) rate ward satisfaction on a 5-point ordinal scale from very poor to very good. Each patient belongs to only one ward. Do the wards differ?", "o": ["Kruskal-Wallis H test", "Friedman test", "One-way ANOVA", "Mann-Whitney U test"], "w": ["Three or more independent groups with an ordinal DV: the H test of William Kruskal and W. Allen Wallis (1952), the rank version of one-way ANOVA. H is referred to χ² with df = k − 1 = 2.", "Milton Friedman's test is for three or more related conditions, with the same people measured under each. It would be right if the same patients had rated all three wards.", "Ronald Fisher's one-way ANOVA compares means and needs an interval DV with roughly normal groups. It would be right for interval scores; with a DV treated as ordinal, the rank-based test is the standard choice.", "The U test of Henry Mann and Donald Whitney compares only two independent groups. It would be right with two wards; running it three times for three wards inflates Type I error."], "r": "s14"},
    {"id": "tp-09", "q": "Two senior clinicians independently rank 10 candidates for an M.Phil seat from 1 (best) to 10. The department wants to know how closely the two rank orders agree. Which statistic?", "o": ["Spearman's ρ", "Pearson r", "Kendall's W", "Point-biserial r"], "w": ["The data are ranks from two judges, so Charles Spearman's rank-order correlation fits: ρ = 1 − 6Σd²/[n(n² − 1)], running from +1 (identical orders) to −1 (completely reversed).", "Karl Pearson's r assumes interval scores with roughly normal distributions. It would be right if the clinicians had given marks out of 100 instead of ranks.", "Maurice Kendall's W, the coefficient of concordance, measures agreement among three or more judges' rankings. It would be right if a panel of, say, five clinicians ranked the candidates.", "Point-biserial r is for a true dichotomy (such as selected or not) against a continuous score. Neither variable here is a dichotomy."], "r": "s12"},
    {"id": "tp-10", "q": "A researcher wants the correlation between sex (male or female, a genuine two-category variable) and interval-level scores on a test anxiety scale among 120 Bangalore undergraduates. Which coefficient?", "o": ["Point-biserial r", "Biserial r", "Phi coefficient (φ)", "Spearman's ρ"], "w": ["One true dichotomy plus one continuous variable: the point-biserial r, which is simply Karl Pearson's r with the dichotomy coded 0 and 1. It is also a common item-total index in item analysis.", "Biserial r is for an artificial dichotomy, a continuous variable cut into two, such as pass or fail made from exam marks. It would be right if the two categories came from splitting a continuous score.", "Phi is for two true dichotomies in a 2 × 2 table, φ = √(χ²/N). It would be right if anxiety had also been recorded only as present or absent.", "Charles Spearman's ρ is for two sets of ranks or ordinal data. It would be right if both variables were ranked; a true dichotomy with continuous scores calls for point-biserial."], "r": "s12"},
    {"id": "tp-11", "q": "A study asks whether CBT or medication works better for depression, and whether the answer is different for men and women. Each patient falls in one of the four therapy-by-sex cells, and the DV is an interval depression score. Which analysis?", "o": ["Two-way factorial ANOVA", "Two separate one-way ANOVAs", "MANOVA", "ANCOVA"], "w": ["Two IVs (therapy, sex) crossed in a 2 × 2 design: Ronald Fisher's factorial ANOVA gives both main effects and the therapy × sex interaction, and the interaction is exactly the question 'is the answer different for men and women'.", "Separate one-way ANOVAs give each main effect but cannot test the interaction, which is the whole point here. They would only fit if each IV were studied in its own separate experiment.", "MANOVA is for two or more DVs analysed together. It would be right if depression, anxiety and quality of life were all outcomes; here there is one DV.", "ANCOVA adjusts group means for a continuous covariate such as baseline severity. Sex here is a categorical IV whose interaction with therapy is of interest, not a nuisance variable to partial out."], "r": "s10"},
    {"id": "tp-12", "q": "To compare two memory-training methods, 14 pairs of children are matched on IQ; one child in each pair gets Method A and the other gets Method B. Recall scores are small counts and the within-pair differences are badly skewed. Which test?", "o": ["Wilcoxon signed-rank test", "Mann-Whitney U test", "Paired-samples t test", "Independent-samples t test"], "w": ["Matching makes the two samples related even though the children are different people, and the skewed differences rule out t. Frank Wilcoxon's signed-rank test ranks the absolute within-pair differences and uses both their direction and size.", "The U test of Henry Mann and Donald Whitney is for two independent groups. It would be right if the children had been split into two groups with no matching; matching makes the scores related.", "The paired t of William Sealy Gosset (\"Student\") is right for matched pairs when the differences are roughly normal. Here they are badly skewed with only 14 pairs, so the rank test is safer.", "The independent t wrongly treats matched children as unrelated and also assumes normal data. It would be right for two unmatched groups with roughly normal interval scores."], "r": "s14"},
    {"id": "tp-13", "q": "Two intact Class 8 sections in a Bengaluru school are compared after one gets a new reading programme. The programme section happened to score higher on the reading pre-test. The researcher wants to compare post-test means after statistically adjusting for pre-test scores.", "o": ["ANCOVA with pre-test as covariate", "Independent t on post-test scores", "MANOVA", "Paired t, pre-test vs post-test"], "w": ["Analysis of covariance, Ronald Fisher's ANOVA extended with a regression step, adjusts each group's DV mean for a continuous covariate (pre-test) and shrinks the error term. It assumes homogeneity of regression slopes, and it is statistical control, not a cure for non-random groups.", "A t test on post-test scores ignores the programme section's head start, so any difference could just be the pre-test gap. It would be right if the groups were equivalent at baseline, as random assignment aims to make them.", "MANOVA analyses two or more DVs at once. It would be right if reading, spelling and comprehension were all outcomes; here there is one DV and one covariate.", "A paired t on pre versus post shows whether one section improved, not whether the programme beat the other section. It answers a within-group question, not the between-group one asked here."], "r": "s11"},
    {"id": "tp-14", "q": "A NIMHANS team wants to predict whether a first-episode patient will relapse within a year (yes or no) from age, duration of untreated illness and a medication-adherence score. Which analysis?", "o": ["Logistic regression", "Multiple linear regression", "Chi-square test of independence", "MANOVA"], "w": ["When the outcome being predicted is a yes/no category, logistic regression models the log odds, ln[P/(1 − P)], from several predictors at once. Its exponentiated coefficients are odds ratios, shown as Exp(B) in SPSS.", "Multiple linear regression needs a continuous DV; with a 0/1 outcome it can predict impossible values below 0 or above 1. It would be right for predicting a continuous score such as a symptom rating.", "Karl Pearson's chi-square tests whether two categorical variables are associated. It could link relapse with one categorical factor, but it cannot weigh three predictors, two of them continuous, at once.", "MANOVA has categorical IVs and two or more continuous DVs. Here the roles are reversed: continuous predictors and a single categorical outcome."], "r": "s13"}
  ]},
  {k: "dd", name: "Design Detective", icon: "🔎", sub: "Spot the design: experimental, quasi, correlational, case study, longitudinal vs cross-sectional", n: "research design", qs: [
    {"id": "dd-01", "q": "At a Bengaluru college, 80 students with exam anxiety are assigned by a computer-generated random list to a 4-week mindfulness course or a waitlist. Both groups fill in an anxiety scale before and after. Which design is this?", "o": ["True experiment", "Quasi-experiment", "Correlational study", "Case study"], "w": ["The researcher manipulates the IV (course vs waitlist) and a random process decides who goes where, so the groups are equal within chance on everything. Random assignment, Ronald A. Fisher's principle, is the defining mark of a true experiment.", "A quasi-experiment also manipulates the IV but uses intact groups with no random assignment, as when one class gets the course and another does not. Here a random list decided group membership.", "A correlational study manipulates nothing; it measures two variables in the same people and computes r, e.g. hours of meditation and anxiety in 300 students. Here the course was deliberately given to one group.", "A case study is an intensive, idiographic account of one person, family or institution, like the amnesic patient H.M. Here 80 people are compared across randomly formed conditions."], "r": "s20"},
    {"id": "dd-02", "q": "A school counsellor in Mysuru gives a 6-week study-skills programme to Class 8A. Class 8B, a section the school formed long ago, gets nothing. Both sections take the same test before and after. Which design is this?", "o": ["Quasi-experiment", "True experiment", "Correlational study", "Case study"], "w": ["The IV is manipulated, but the groups are intact sections, not randomly formed: a quasi-experiment, the term of Donald T. Campbell and Julian C. Stanley. With the pretest it is their nonequivalent control group design.", "A true experiment needs random assignment of individuals. It would be right if the counsellor had pooled all Class 8 pupils and randomly allocated each one to programme or no programme.", "A correlational study measures existing variables and gives no treatment, e.g. correlating hours of self-study with marks. Here the counsellor deliberately gave the programme to one section.", "A case study examines one person or unit in depth with no comparison group, e.g. a detailed account of one struggling pupil. Here two whole sections are compared before and after."], "r": "s20"},
    {"id": "dd-03", "q": "A clinical psychologist at NIMHANS writes a detailed account of one 34-year-old man with dissociative fugue, built from months of interviews, family reports, hospital records and test results. Nothing is manipulated and no baseline or treatment phases are planned. Which design is this?", "o": ["Case study", "Single-subject ABAB design", "Correlational study", "Quasi-experiment"], "w": ["A case study is an intensive, usually long-term, idiographic study of one person using interviews, records and tests, like Sigmund Freud's Little Hans or the amnesic patient H.M. It generates hypotheses but cannot establish causation.", "ABAB also has N = 1, but it manipulates treatment in planned phases (baseline, treatment, withdrawal, treatment) with repeated measurement, as Michel Hersen and David H. Barlow set out. Nothing is manipulated here.", "A correlational study measures two or more variables across many people and computes how they covary (r). One man studied in depth gives nothing to correlate.", "A quasi-experiment introduces a treatment to intact groups without random assignment, e.g. a new programme on one ward compared with another ward. Here there is no treatment and no comparison group."], "r": "s21"},
    {"id": "dd-04", "q": "To see how working memory develops, a researcher in Pune tests 200 children aged 6, 9 and 12 from the same schools, all in one week of 2026. Which design is this?", "o": ["Cross-sectional design", "Longitudinal design", "Cross-sequential design", "Time-lag design"], "w": ["Different age groups tested at one time is cross-sectional. It is quick and free of attrition, but in K. Warner Schaie's terms it confounds age with cohort, so it shows age differences, not age changes.", "A longitudinal design tests the same children repeatedly as they age, e.g. the 6-year-olds again at 9 and 12. It would show age changes within the same children; here each child is tested once.", "A cross-sequential design combines the two: several age cohorts are each followed over time. It would be right if these three age groups were all retested in later years.", "A time-lag design tests people of the same age at different times (12-year-olds in 2006, 2016 and 2026), holding age constant. Here ages differ and the testing time is fixed."], "r": "s21"},
    {"id": "dd-05", "q": "In 2024 a researcher tests children aged 6, 9 and 12 on working memory, then retests the same children in 2027 and 2030, so each age group is followed for six years. Which design is this?", "o": ["Cross-sequential design", "Longitudinal design", "Cross-sectional design", "Trend study"], "w": ["Several cohorts, each followed over time, combine the cross-sectional and longitudinal approaches: a sequential design (K. Warner Schaie, 1965). Because the cohorts cover overlapping ages, age changes can be checked against cohort differences, which neither simple design allows.", "Plain longitudinal follows one cohort, e.g. only the 6-year-olds retested at 9 and 12, and confounds age with time of measurement. Here three age cohorts are followed at once.", "The 2024 wave alone is cross-sectional: several ages at one time, confounding age with cohort. Retesting the same children in 2027 and 2030 makes the design more than that.", "A trend study draws fresh samples from the same population at each wave, as in the National Family Health Survey rounds, and shows population change. Here the same children are retested."], "r": "s21"},
    {"id": "dd-06", "q": "Researchers compare 60 adolescents who were bullied at school with 60 never-bullied classmates, matched on age, sex and family income, on a social anxiety scale given once. Which design is this?", "o": ["Ex post facto (causal-comparative) study", "Quasi-experiment", "Matched-groups true experiment", "Prospective cohort study"], "w": ["The IV (bullying) has already happened and cannot be manipulated, so groups are picked by it and compared on the DV: what Fred N. Kerlinger called ex post facto research. Matching equates only the measured variables; self-selection remains.", "A quasi-experiment lacks random assignment, but the researcher still introduces the treatment, e.g. an anti-bullying programme run in one school and not another. Nobody here administered the bullying.", "Matching does not make an experiment. A matched-groups experiment matches people, then randomly assigns each member of a pair to a condition the researcher controls; bullying cannot be assigned.", "A prospective cohort study would classify adolescents by exposure now and follow them for years to see who develops social anxiety, like Richard Doll and Austin Bradford Hill's British Doctors Study. Here everyone is measured once."], "r": "s21"},
    {"id": "dd-07", "q": "A deaddiction centre in Bengaluru rates craving in 25 inpatients, runs a 6-week relapse-prevention group, then rates them again. Mean craving falls from 31 to 18, and the centre credits the group. Which design is this?", "o": ["One-group pretest-posttest design", "One-shot case study", "Static-group comparison", "Pretest-posttest control group design"], "w": ["O X O: one group measured, treated, measured again, a pre-experimental design of Donald T. Campbell and Julian C. Stanley. The fall could be history, maturation, testing, instrumentation or regression to the mean; nothing rules them out.", "The one-shot case study (X O) treats a group and measures only afterwards, with no pretest at all. It would fit if the centre had simply reported low craving at the end.", "The static-group comparison (X O over O, intact groups) compares a treated group with an untreated one, measured only after. It would fit if a second ward without the group had been rated at the end.", "The pretest-posttest control group design (R O X O over R O O) adds a randomly assigned control group, which cancels history, maturation and regression. There is no control group here."], "r": "s20"},
    {"id": "dd-08", "q": "At NIMHANS, 120 depressed outpatients are randomly assigned to one of four groups: CBT plus sertraline, CBT plus placebo, supportive counselling plus sertraline, or supportive counselling plus placebo. The HAM-D is rated at week 12. Which design is this?", "o": ["2 × 2 factorial design", "Solomon four-group design", "Within-subjects (repeated measures) design", "Randomised block design"], "w": ["Two IVs (therapy, medication) are crossed so every level of one meets every level of the other: a 2 × 2 factorial, set out by Ronald A. Fisher (1935). Only a factorial design can reveal an interaction, e.g. CBT helping more without the drug.", "The Solomon four-group design (Richard L. Solomon, 1949) also has four random groups, but its second factor is pretested vs not pretested, to measure pretest sensitisation. Here both factors are treatments.", "In a within-subjects design each person receives every condition, with orders counterbalanced. Here each patient gets only one of the four combinations, so all comparisons are between subjects.", "A randomised block design first groups patients into blocks on a nuisance variable (e.g. severity) and randomises within each block; the block is not a treatment. No blocking is described here."], "r": "s20"},
    {"id": "dd-09", "q": "Testing an anti-stigma film, a researcher fears the attitude pretest itself may sensitise students to it. She randomly splits 120 students into four groups: pretest, film, posttest; pretest, posttest; film, posttest; posttest only. Which design is this?", "o": ["Solomon four-group design", "Pretest-posttest control group design", "Posttest-only control group design", "Nonequivalent control group design"], "w": ["Richard L. Solomon (1949) combined the pretest-posttest and posttest-only control designs, all four groups random. It controls and measures pretest sensitisation (testing × treatment), analysed as a 2 × 2 ANOVA on the posttests, as Donald T. Campbell and Julian C. Stanley advised.", "R O X O over R O O is only the first two groups. It controls all eight internal threats but leaves pretest sensitisation, the very worry here, unmeasured.", "R X O over R O is only the last two groups: dropping the pretest avoids sensitisation but cannot measure it or check initial equivalence. It would be right if only groups 3 and 4 existed.", "The nonequivalent control group design (O X O over O O) uses intact groups with no random assignment, a quasi-experiment. Here all four groups were formed at random."], "r": "s20"},
    {"id": "dd-10", "q": "Three children with autism at a Bengaluru special school bang their heads daily. Withdrawing an effective treatment would be unethical, so the therapist records all three from day 1 and starts treatment for Aarav in week 2, Meera in week 4 and Kabir in week 6. Which design is this?", "o": ["Multiple-baseline design across participants", "ABAB (withdrawal) design", "Changing-criterion design", "Alternating-treatments design"], "w": ["Baselines run at once and treatment is staggered; if each child improves only when treatment reaches them, history is ruled out without ever withdrawing treatment. Donald M. Baer, Montrose M. Wolf and Todd R. Risley (1968) described it.", "ABAB (baseline, treatment, withdrawal, treatment) shows control by removing and reinstating treatment in one person. It suits reversible, harmless behaviour such as being out of seat; for head-banging withdrawal is ruled out.", "The changing-criterion design (Donald P. Hartmann and R. Vance Hall, 1976) shifts one behaviour gradually through stepwise criteria, e.g. cigarettes cut from 18 to 3 a day. Here treatment is staggered across children, not stepped.", "The alternating-treatments design (David H. Barlow and Steven C. Hayes, 1979) rapidly alternates two or more treatments in one person to compare them. Here one treatment starts at staggered times for three children."], "r": "s22"},
    {"id": "dd-11", "q": "Autism is rare, so researchers start with 45 children with autism from a Bengaluru clinic and 90 typically developing children matched on age and sex, then ask all the mothers about fever during pregnancy. Which design is this?", "o": ["Case-control study", "Retrospective cohort study", "Prospective cohort study", "Cross-sectional survey"], "w": ["Starting from the outcome (cases vs matched controls) and looking back at exposure is a case-control study, as in Richard Doll and Austin Bradford Hill's 1950 lung cancer study. Efficient for rare disorders, it gives an odds ratio and is open to recall bias.", "A retrospective cohort also uses the past, but starts from exposure recorded in old files (antenatal notes of fever) and traces forward to who later got autism. Here groups were chosen by outcome.", "A prospective cohort recruits pregnant women now, records fever, and follows the children for years to see who develops autism. It gives incidence and relative risk but is slow for rare outcomes.", "A cross-sectional survey samples a population at one time without regard to outcome and gives prevalence, like the National Mental Health Survey 2015-16. Here sampling was fixed by autism status."], "r": "s21"},
    {"id": "dd-12", "q": "A new antidepressant is tested against an identical-looking placebo. A central computer randomises 200 patients. The hospital pharmacist holds the code, but neither the patients nor the psychiatrists who prescribe and rate the HAM-D know who got which. Which design is this?", "o": ["Double-blind randomised controlled trial", "Single-blind randomised controlled trial", "Assessor-blind (rater-blind) trial", "Open-label trial"], "w": ["Random allocation plus blinding of both patients and the clinicians who treat and rate them is a double-blind RCT; a pharmacist holding the code does not break it. It controls participant expectancy and experimenter bias, which Robert Rosenthal demonstrated.", "Single-blind means only one party, usually the patient, is unaware, as when the psychiatrists know who got the drug. Here the prescribing and rating psychiatrists are blind too.", "Assessor-blind means only the outcome rater is blind, typical of psychotherapy trials where patient and therapist cannot help knowing the treatment. Here the patients are blind as well.", "Open-label means everyone knows the allocation, e.g. a drug compared with no pill at all. The identical placebo and the hidden code rule it out."], "r": "s25"}
  ]},
  {k: "vs", name: "Variable Sort", icon: "🧪", sub: "Sort the highlighted item: IV, DV, confound, extraneous, moderator, mediator", n: "extraneous variable", qs: [
    {"id": "vs-01", "q": "At a Bangalore hospital, 60 adults with depression are randomly assigned to 0, 4 or 8 weekly yoga sessions, and their Hamilton depression (HAM-D) scores are compared two months later. In this study, what is 'number of yoga sessions'?", "o": ["Independent variable", "Dependent variable", "Extraneous variable", "Confounding variable"], "w": ["The independent variable is the presumed cause that the researcher manipulates. Here it has three levels (0, 4 and 8 sessions): one IV, not three. Fred Kerlinger would call it an active variable because it is assigned, not measured.", "The dependent variable is the measured outcome expected to change with the IV, here the HAM-D score. Session count would be the DV only if the study measured how many sessions people chose to attend.", "An extraneous variable is anything other than the IV that could affect HAM-D, such as baseline severity or medication. The number of sessions is the IV itself, so it cannot be extraneous to the study.", "A confound is a third variable that varies systematically with the IV and offers a rival explanation, for example if only the 8-session group had the most experienced instructor. Session number is the IV itself, not a rival to it."], "r": "s18"},
    {"id": "vs-02", "q": "In a Bangalore school, 40 children are randomly assigned to watch either an aggressive or a calm cartoon. Each child's aggression is then recorded as the number of hits, kicks and punches given to a Bobo doll in 20 minutes. What is 'number of hits, kicks and punches in 20 minutes'?", "o": ["Dependent variable", "Independent variable", "Extraneous variable", "Confounding variable"], "w": ["It is the dependent variable, and an operational definition of aggression: a concept defined by the operations that measure it (Percy Bridgman, 1927; brought into psychology by Stanley Smith Stevens, 1935), as in Albert Bandura, Dorothea Ross and Sheila Ross's 1961 Bobo doll study.", "The independent variable is the type of cartoon, which the researcher assigned. The hit count is recorded afterwards as the result; it would be an IV only if children were grouped by hit count to predict something else.", "An extraneous variable is something besides the IV that might affect the outcome, such as a child's age or a noisy room. The hit count is the outcome itself, so it is the DV, not a stray influence on it.", "A confound is a stray variable that differs systematically between the two cartoon groups, for example if the aggressive-cartoon group were all older boys. The hit count is the outcome being measured, not a rival cause of it."], "r": "s18"},
    {"id": "vs-03", "q": "Anxious outpatients are randomly assigned to relaxation training or a waiting list, and anxiety is measured after four weeks. Testing ran from 9 a.m. to 5 p.m.; each patient's slot was drawn at random, so both groups had a similar mix of morning and afternoon sessions. What is 'time of testing'?", "o": ["Extraneous variable", "Confounding variable", "Independent variable", "Dependent variable"], "w": ["An extraneous variable is any variable other than the IV that could affect the DV. Spread at random across groups, time of day only adds noise (error variance, which lowers power) and offers no rival explanation. Ronald Fisher made randomisation the standard guard against confounding.", "It would be a confound only if it varied systematically with the IV, for example every relaxation patient tested in the morning and every waiting-list patient in the afternoon. Randomly drawn slots rule that out.", "The IV is relaxation versus waiting list. Time of day would be an IV only if the researcher deliberately compared morning with afternoon testing as conditions of the study.", "The DV is the anxiety score measured at four weeks. Time of testing is not the outcome; it is a background condition that could nudge the outcome."], "r": "s18"},
    {"id": "vs-04", "q": "A psychologist trains the nurses of Ward A in de-escalation; Ward B gets no training. Ward A is an open ward with voluntary, milder patients, while Ward B is a closed ward for acutely ill patients. Ward A later records fewer aggressive incidents. At its most specific, what is 'how acutely ill the patients are'?", "o": ["Confounding variable", "Extraneous variable", "Independent variable", "Dependent variable"], "w": ["Acuity differs systematically between the trained and untrained wards and can itself drive aggression, so it is a rival explanation for Ward A's fewer incidents. An extraneous variable that varies with the IV is a confounding variable; comparable wards or random assignment would remove it.", "Acuity starts as an extraneous variable, anything other than the IV that could affect incidents. It would stay merely extraneous if milder and acute patients were spread evenly across both wards; because it differs between the wards, it is a confound.", "The IV is de-escalation training versus none, the condition the psychologist introduced. Acuity would be an IV only if the study deliberately compared milder with acutely ill patients.", "The DV is the number of aggressive incidents, the measured outcome. Acuity would be a DV only if the study asked whether training changed how ill the patients became."], "r": "s18"},
    {"id": "vs-05", "q": "At NIMHANS, a researcher compares digit-span scores of 30 inpatients with schizophrenia and 30 healthy controls matched for age and education. What kind of variable is 'diagnosis' in this study?", "o": ["Attribute (organismic) IV", "Manipulated (active) IV", "Dependent variable", "Confounding variable"], "w": ["Diagnosis defines the groups being compared, so it is the IV, but participants bring it with them: it can be selected, not manipulated. Fred Kerlinger called this an attribute variable (also organismic or subject variable), so the study is ex post facto, not a true experiment.", "An active IV is one the researcher creates and assigns, such as a drug dose or a type of therapy. Nobody can assign schizophrenia; an active IV here would be, say, a memory drug given to a random half of the patients.", "The DV is the measured outcome, the digit-span score. Diagnosis would be the DV only in a study predicting who develops schizophrenia, for example from childhood cannabis use.", "A confound is a third variable that varies with the IV and offers a rival explanation, such as antipsychotic medication, which only the patients take. Diagnosis is the comparison itself, not a rival to it."], "r": "s18"},
    {"id": "vs-06", "q": "Students are randomly assigned to learn a 30-word list either with background music or in silence. Temperature might affect recall, so every participant is tested alone, at 10 a.m., in the same room kept at 24°C. In this study, what is 'room temperature'?", "o": ["Control variable (held constant)", "Confounding variable", "Independent variable", "Moderator variable"], "w": ["A variable deliberately fixed at one value for everyone is a control variable. Holding constant is one of the techniques Fred Kerlinger grouped under controlling extraneous variance (the 'CON' of his MAXMINCON principle); its cost is that results strictly apply only at that temperature.", "A confound varies systematically with the IV. Temperature would be a confound if the music group sat in a warm room and the silence group in a cool one; at a fixed 24°C it cannot differ between groups.", "The IV is music versus silence. Temperature would be an IV only if the researcher deliberately set different temperatures, say 18°C and 30°C, to see their effect on recall.", "A moderator changes the strength or direction of the IV's effect. Temperature could be tested as a moderator only if it varied, for instance if music helped recall in a cool room but hurt it in a hot one."], "r": "s19"},
    {"id": "vs-07", "q": "In a survey of 300 Bangalore IT employees, work stress predicted depressive symptoms strongly among those with little social support, but only weakly among those with strong social support. What is 'social support' here?", "o": ["Moderator variable", "Mediator variable", "Confounding variable", "Dependent variable"], "w": ["Social support changes the strength of the stress to depression link, which is moderation (here a buffering effect), tested as a stress × support interaction. Reuben Baron and David Kenny (1986) defined a moderator as a variable that alters the strength or direction of a relation.", "A mediator is the mechanism the effect passes through: stress would cause something, such as poor sleep, which then causes depression. Support is not produced by stress here; it sets how strongly stress matters.", "A confound causes both X and Y and makes their link spurious, for example a chronic illness that raises both stress and depression. Social support does not create the stress and depression link; it weakens it.", "The DV (criterion) is depressive symptoms. Social support would be the outcome only if the study asked whether work stress erodes people's support networks."], "r": "s18"},
    {"id": "vs-08", "q": "In a randomised trial at a Chennai clinic, CBT lowered depression scores. CBT also reduced patients' negative automatic thoughts, and once these thoughts were statistically controlled, the effect of CBT on depression shrank almost to zero. What is 'negative automatic thoughts'?", "o": ["Mediator variable", "Moderator variable", "Confounding variable", "Organismic (subject) variable"], "w": ["A mediator is the mechanism: CBT changes automatic thoughts (path a), which change depression (path b). When controlling the mediator shrinks the direct effect (c′) to about zero, mediation is full, what Reuben Baron and David Kenny (1986) called perfect mediation.", "A moderator is not changed by the treatment; it decides for whom or how strongly CBT works, such as baseline severity. Here CBT changed the thoughts, so they lie on the causal path, not beside it.", "A confound would have to cause both who gets CBT and later depression. With random assignment nothing pre-existing decides who gets CBT; the thoughts changed because of CBT, so they are its route, not a rival.", "Organismic variables are characteristics participants bring and the IV does not change, like age, sex or diagnosis. Automatic thoughts shifted with treatment, which marks them as a mechanism, not a subject variable."], "r": "s18"},
    {"id": "vs-09", "q": "Depressed outpatients are randomly assigned to placebo, 50 mg or 100 mg of sertraline for eight weeks, and HAM-D scores are compared. In this study, what is 'the placebo condition'?", "o": ["A level of the independent variable", "Control variable (held constant)", "Extraneous variable", "Dependent variable"], "w": ["The IV is drug dose with three levels: placebo (0 mg), 50 mg and 100 mg. A placebo or control condition is one level of the IV, the zero-dose comparison, not a separate kind of variable.", "Do not mix up a control group with a control variable. A control variable is held at one value for every group, such as identical-looking capsules or the same rater; the placebo condition differs from the other groups on purpose.", "Extraneous variables are factors besides the IV that might affect HAM-D, such as expectations or baseline severity. The placebo arm is built into the IV by design, precisely to equalise expectation across the levels.", "The DV is the HAM-D score measured at eight weeks. A condition that patients are assigned to can never be the DV, which is always what is measured afterwards."], "r": "s18"},
    {"id": "vs-10", "q": "Students are randomly assigned to relaxation training or a study-skills control group for exam anxiety. Dr Rao runs every relaxation session and Dr Iyer runs every control session. The relaxation group ends less anxious. At its most specific, what is 'which psychologist ran the sessions'?", "o": ["Confounding variable", "Extraneous variable", "Moderator variable", "Control variable (held constant)"], "w": ["The psychologist changes in lockstep with the IV: every relaxation student had Rao, every control student had Iyer. An extraneous variable that varies systematically with the IV is a confound, a rival explanation (perhaps Rao's warmth) that random assignment of students cannot remove.", "It did begin as an extraneous variable, anything besides the IV that could affect anxiety. It would stay merely extraneous if each psychologist ran half the sessions of both groups; tied to one group, its precise name is confound.", "A moderator would mean relaxation worked better with one psychologist than the other, which needs both psychologists in both conditions. Here they never overlap, so their effects cannot even be separated.", "Holding it constant, with one psychologist running every session, would make it a control variable and remove the confound. Two people, one per group, is the opposite of holding it constant."], "r": "s19"},
    {"id": "vs-11", "q": "To study sleep loss and reaction time, a researcher recruits only right-handed men aged 20 to 25 and randomly assigns them to a sleepless night or a normal night. In this study, what is 'sex'?", "o": ["Control variable (held constant)", "Attribute (organismic) IV", "Confounding variable", "Moderator variable"], "w": ["Sex could affect reaction time, so it was removed as a source of difference by recruiting only men: it is held constant, a control variable. The price is external validity, since the result strictly applies only to young right-handed men.", "Sex is a subject (organismic) characteristic, but an IV must take at least two values. With only men it is a constant; it would be an attribute IV if men and women were compared on reaction time.", "A confound differs systematically between conditions. Both groups are all men, so sex cannot differ between them; it would be a confound if the sleepless group were men and the normal-sleep group women.", "A moderator would show that sleep loss slows men and women by different amounts. With only one sex in the sample, no moderation by sex can be tested."], "r": "s19"},
    {"id": "vs-12", "q": "In a survey of 500 Delhi college students, heavier Instagram use went with more depressive symptoms. Loneliness, measured a year earlier, predicted both later Instagram use and later depression. For the Instagram and depression link, what is 'loneliness'?", "o": ["Confounding variable", "Mediator variable", "Moderator variable", "Dependent variable"], "w": ["Loneliness came first and is linked to both the presumed cause (Instagram use) and the outcome (depression), so it could produce their correlation with no causal link between them. A third variable that influences both X and Y is a confounding variable.", "A mediator is caused by X and carries its effect: Instagram use would raise loneliness, which then raises depression. Loneliness measured a year before the Instagram use comes first, so it sits behind both variables, not between them.", "A moderator changes the strength of the X to Y link, for example Instagram use predicting depression only in lonely students. The finding here is that loneliness drives both variables, not that it alters their relation.", "Depressive symptoms are the outcome (criterion). Loneliness would be the DV only if the question were whether Instagram use makes students lonelier."], "r": "s18"}
  ]},
  {k: "rv", name: "Reliability vs Validity", icon: "⚔️", sub: "Duels: two look-alikes, one of them is right", n: "reliability validity", qs: [
    {"id": "rv-01", "q": "A developer builds two versions of a 40-item vocabulary test, Form A and Form B, matched for content and item difficulty. 200 students take Form A and then Form B in the same sitting, and the two scores correlate .88. What has she estimated?", "o": ["Alternate (parallel) forms reliability", "Test-retest reliability"], "w": ["Two equivalent forms given to the same people and correlated give the coefficient of equivalence. Its error source is content sampling (which particular items were chosen), and it needs truly parallel forms with equal means and variances, which are costly to build.", "Test-retest gives the same form twice, separated by time, and yields the coefficient of stability (time-sampling error). It would be right if Form A were given again a month later; two different forms make this alternate forms."], "r": "s15"},
    {"id": "rv-02", "q": "A 10-minute clerical speed test is given to 100 bank trainees, and the same test is given again to the same trainees two weeks later. The two sets of scores are correlated. Which reliability is this?", "o": ["Test-retest reliability", "Split-half reliability"], "w": ["Giving the same test to the same people on two occasions and correlating the scores is test-retest reliability, the coefficient of stability. Too short an interval inflates it through memory and practice; too long deflates it through real change.", "Split-half correlates two halves from one sitting, then corrects with the Spearman-Brown formula (Charles Spearman and William Brown, 1910). It suits a power test split odd-even; on a pure speed test odd-even halves correlate spuriously high, so test-retest or separately timed halves are used."], "r": "s15"},
    {"id": "rv-03", "q": "A new 'depression' questionnaire gives nearly identical scores when students retake it a month later (r = .90), and its items intercorrelate highly. But it correlates .70 with a reading-speed test and only .08 with psychiatrists' ratings of depression. What does it have?", "o": ["Reliability, not validity", "Validity, not reliability"], "w": ["Reliability is consistency; validity is whether the test measures what it claims to. This scale consistently measures something (apparently reading speed) but not depression: reliable but not valid, like a bathroom scale that always reads 10 kg heavy.", "Validity needs reliability first, because reliability caps validity at √r_xx. The 'valid but not reliable' corner of the target diagram means scores centred on the target but scattered; these scores are tightly consistent (.90) and off target."], "r": "s15"},
    {"id": "rv-04", "q": "For a new depression scale, the developer asks five clinical psychologists to check every item against a blueprint of all nine DSM-5 symptoms of major depression. They find two symptoms uncovered, and items are added for them. Which validity is being built?", "o": ["Content validity", "Face validity"], "w": ["Content validity asks whether the items adequately sample the whole domain, judged systematically by experts against a blueprint (table of specifications). It is built in while writing and reviewing items, not computed from a single correlation.", "Face validity is whether the test looks relevant to test-takers or lay readers, a surface impression rather than systematic expert sampling. It would fit if patients were asked whether the items seemed to be about low mood."], "r": "s15"},
    {"id": "rv-05", "q": "A single clinician completes a 20-item yes/no symptom checklist for each of 150 ward patients. From the item scores the developer computes KR-20 and gets .86. What has she estimated?", "o": ["Internal consistency reliability", "Inter-rater reliability"], "w": ["KR-20 (G. Frederic Kuder and Marion Richardson, 1937) measures internal consistency for yes/no or right/wrong items from one administration; Cronbach's alpha (Lee Cronbach, 1951) is its general form for multi-point items. Who fills in the form does not change that.", "Inter-rater reliability needs two or more raters scoring the same patients independently, summarised by Cohen's kappa (Jacob Cohen, 1960) for categories or an intraclass correlation. With one clinician there is no second rater to agree with."], "r": "s15"},
    {"id": "rv-06", "q": "Validating a new loneliness scale, the developer is pleased that it correlates only .10 with a social desirability scale, a construct it should not be measuring. What evidence is this low correlation?", "o": ["Discriminant validity", "Convergent validity"], "w": ["Discriminant (divergent) validity is a low correlation with measures of a construct the test should not reflect. With convergent evidence it builds construct validity, and the multitrait-multimethod matrix of Donald Campbell and Donald Fiske (1959) tests both together.", "Convergent validity is a high correlation with other measures of the same construct, such as an established loneliness scale or peer ratings of isolation. A low correlation with a different construct is the other half of the picture."], "r": "s15"},
    {"id": "rv-07", "q": "A hospital wants a test to select future trainee counsellors. To save time, it gives the test to 60 counsellors already employed and correlates their scores with supervisors' current ratings of their work. Which validity has it estimated?", "o": ["Concurrent validity", "Predictive validity"], "w": ["Concurrent validity correlates a test with a criterion obtained at about the same time. Anne Anastasi noted that testing present employees is a common shortcut for predictive validity, but with test and criterion collected together, the design is concurrent.", "Predictive validity needs a time gap: test the applicants first, then correlate with a criterion gathered later, such as supervisors' ratings after a year in the job. That is what the hospital ultimately wants, not what it did."], "r": "s15"},
    {"id": "rv-08", "q": "On a 1 to 5 scale of clinical skill, a ward supervisor gives 27 of her 30 trainees a 3 and never uses 1 or 5, although the trainees clearly differ in skill. Which rater error is this?", "o": ["Central tendency error", "Leniency error"], "w": ["Central tendency error is avoiding the extremes and piling ratings in the middle of the scale, which hides real differences between people. Joy Paul Guilford's Psychometric Methods (1954) gives the standard list of these constant rater errors.", "Leniency (generosity) error is rating everyone too favourably, such as 4s and 5s for all; its mirror image is severity error. Ratings stuck at the midpoint are non-committal, not generous."], "r": "s23"},
    {"id": "rv-09", "q": "An MPhil interview panel sees a brilliant candidate, then an average one. The average candidate is scored well below the cut-off, although against the fixed marking scheme her answers were satisfactory. Which rater error is this?", "o": ["Contrast error", "Halo effect"], "w": ["Contrast error is rating a person relative to the one just rated (or opposite to the rater's own standing) instead of against the fixed standard. After a brilliant candidate, an ordinary one looks worse than she is.", "The halo effect is one salient trait or overall impression colouring ratings of all other traits, named by Edward Thorndike (1920). It would fit if the panel, charmed by her fluent English, also rated her research knowledge and empathy high."], "r": "s23"},
    {"id": "rv-10", "q": "A developer scores the odd and even halves of a test. The halves have clearly unequal variances, so instead of correlating them she uses each person's odd-minus-even difference score: r = 1 - σ²d / σ²x = 1 - 12/48 = .75. Which formula is this?", "o": ["Rulon's formula", "Spearman-Brown prophecy formula"], "w": ["Phillip Rulon (1939) estimated split-half reliability from the variance of the difference scores relative to total-score variance. It needs no correlation and no assumption of equal half variances; when the halves are equal it gives the same answer as Spearman-Brown.", "The Spearman-Brown formula (Charles Spearman and William Brown, 1910) steps up the half-test correlation, 2r / (1 + r), assuming equal halves; its general form predicts reliability for any change in length. It would be right if she had correlated the two halves."], "r": "s15"},
    {"id": "rv-11", "q": "No accepted criterion exists for 'hope', so the developer of a new hope scale shows that its scores correlate with optimism as theory predicts, rise after a hope-building group programme, and split into the two factors (agency and pathways) the theory specifies. What is this evidence for?", "o": ["Construct validity", "Content validity"], "w": ["When no criterion exists, a test is validated against theory: predicted correlations, change after an intervention and the expected factor structure form the nomological network of Lee Cronbach and Paul Meehl (1955). That pattern is construct validity, the overarching type.", "Content validity is expert judgement that the items sample the whole domain, for example psychologists checking that the items cover every facet of hope. Nothing here is an item review; every piece of evidence is an empirical test of theory."], "r": "s15"},
    {"id": "rv-12", "q": "In a hierarchical regression predicting suicide attempts over the next year, a NIMHANS team enters the Beck Hopelessness Scale first and a new suicide-intent scale second. R² rises from .10 to .18. What evidence does the new scale show?", "o": ["Incremental validity", "Convergent validity"], "w": ["Incremental validity is the gain in predicting a criterion that a new test adds over measures already in use, tested by entering it last in a hierarchical regression: here ΔR² = .18 minus .10 = .08. Lee Sechrest (1963) named it.", "Convergent validity is a high correlation with other measures of the same construct, one half of the multitrait-multimethod logic of Donald Campbell and Donald Fiske (1959). It would fit if the new scale correlated highly with an established suicide-intent scale: overlap, not added prediction."], "r": "s15"},
    {"id": "rv-13", "q": "In a tightly controlled lab experiment with random assignment and blind scoring, undergraduates taught a mnemonic recall far more nonsense syllables than controls. When elderly outpatients use the same mnemonic to remember their medicine schedules at home, it makes no difference. Which validity of the lab study is in question?", "o": ["External validity", "Internal validity"], "w": ["External validity is whether a causal result generalises to other people, settings and tasks. This one fails to carry from undergraduates and nonsense syllables to elderly patients at home: weak population and ecological validity, the split made by Glenn Bracht and Gene Glass (1968).", "Internal validity asks whether the IV really caused the change within the study (Donald Campbell and Julian Stanley, 1963). Random assignment and blind scoring protect it; it would be in doubt if, say, the mnemonic group had been tested in a quieter room."], "r": "s19"},
    {"id": "rv-14", "q": "At a Delhi primary-care clinic, a depression screen is checked against a structured diagnostic interview. Of 80 patients with major depression, 70 screen positive; of 220 without it, 187 screen negative. The report quotes 85%. Which index is that?", "o": ["Specificity", "Sensitivity"], "w": ["Specificity is the proportion of people without the disorder whom the test correctly clears: true negatives / (true negatives + false positives) = 187/220 = 85%. A highly specific screen rarely labels a healthy person as depressed.", "Sensitivity is the proportion of true cases the test catches: true positives / (true positives + false negatives) = 70/80 = 87.5%. It would be the answer if the quoted figure were 87.5%."], "r": "s15"}
  ]},
  {k: "sr", name: "Sampling Run", icon: "🎯", sub: "Name the sampling method from how the people were picked", n: "sampling", qs: [
    {"id": "sr-01", "q": "The names of all 500 first-year students at a Bengaluru college are written on identical slips, put in a drum, mixed well, and 50 slips are drawn. Which sampling method is this?", "o": ["Simple random sampling (lottery method)", "Systematic sampling", "Stratified random sampling", "Convenience sampling"], "w": ["Every student has an equal, independent chance of selection from a complete list: simple random sampling. The lottery method and the random number table are its two classic techniques, and it is the model most textbook inferential formulas assume.", "Systematic sampling takes a random start and then every kth name from an ordered list (here k = 500/50 = 10). No list order or fixed interval is used here; slips are drawn blind.", "Stratified random sampling first splits the population into strata (e.g. arts, science, commerce) and draws randomly within each. Here one undivided pool of 500 slips is used.", "Convenience sampling takes whoever is easily available, such as students in the canteen. Here selection is by chance from the full list, which makes it a probability method."], "r": "s7"},
    {"id": "sr-02", "q": "From an OPD register of 2,000 new patients, a researcher needs 100. She picks a random number between 1 and 20 (it comes out 7), then takes patients 7, 27, 47 and so on down the register. Which sampling method is this?", "o": ["Systematic sampling", "Simple random sampling", "Cluster sampling", "Quota sampling"], "w": ["A random start followed by every kth case, k = N/n = 2000/100 = 20, is systematic sampling. With a random start it is a probability method; it fails only if the list has a cycle that matches k.", "In simple random sampling every possible set of 100 is equally likely, drawn by lottery or random number table. Here, once 7 is drawn, the other 99 are fixed, so it is not simple random.", "Cluster sampling randomly selects whole natural groups (OPD days, wards, villages) and studies everyone in them. Here individual patients are taken at a fixed interval from one list.", "Quota sampling fills preset numbers per subgroup (say 50 men, 50 women) by non-random choice. There are no quotas here, and selection follows a random start."], "r": "s7"},
    {"id": "sr-03", "q": "For her MA dissertation, a student stands outside the college canteen at lunchtime and gives her loneliness questionnaire to the first 60 students who agree to fill it in. Which sampling method is this?", "o": ["Convenience (accidental) sampling", "Simple random sampling", "Quota sampling", "Purposive sampling"], "w": ["Taking whoever is available and willing is convenience, also called accidental or incidental, sampling. It is the cheapest and fastest, but it is non-probability, so sampling error cannot be estimated and external validity is the weakest.", "Simple random sampling would need a full list of students and a lottery or random number table, giving each an equal chance. Lunchtime canteen visitors who agree are not a random draw.", "Quota sampling would fix numbers per subgroup first (e.g. 30 men, 30 women) and then fill them non-randomly. Here she just takes the first 60 who agree, with no quotas.", "Purposive sampling deliberately picks cases judged typical or information-rich, e.g. students already diagnosed with social anxiety. Here nobody is chosen for a characteristic; availability decides."], "r": "s7"},
    {"id": "sr-04", "q": "To study people who inject drugs in Delhi, who appear on no list, a researcher interviews 5 users met through an NGO and asks each to refer others they know. The new participants then refer more. Which sampling method is this?", "o": ["Snowball (chain-referral) sampling", "Convenience sampling", "Cluster sampling", "Quota sampling"], "w": ["Participants recruit further participants: snowball or chain-referral sampling. It is the standard method for hidden or stigmatised groups with no sampling frame, such as people who use drugs, but well-networked people are over-represented.", "Convenience sampling takes whoever is at hand, e.g. only the 5 users at the NGO. The defining step here is that participants refer others, which makes it snowball.", "Cluster sampling randomly selects whole natural groups from a list of groups (e.g. 10 of 80 drop-in centres) and studies everyone in them. No list exists and nothing is chosen by chance here.", "Quota sampling fills preset numbers per subgroup (say 20 men, 20 women) by non-random choice. No quotas are set here; the sample grows through referral chains."], "r": "s7"},
    {"id": "sr-05", "q": "A district has 1,000 government school teachers: 600 women and 400 men. Using two separate lists, a researcher draws 60 women and 40 men with a random number table. Which sampling method is this?", "o": ["Proportionate stratified random sampling", "Disproportionate stratified random sampling", "Quota sampling", "Cluster sampling"], "w": ["The population is divided into strata (sex) and each is sampled randomly in proportion to its size: 60/600 = 40/400 = 10%. Proportionate stratified sampling guarantees every stratum and usually gives less sampling error than simple random sampling.", "Disproportionate stratified sampling uses different sampling fractions, e.g. 50 women and 50 men, to oversample a smaller stratum. Here both strata are sampled at the same 10%.", "Quota sampling would fix the same 60 and 40 but let the researcher pick whoever is convenient within each group. Here selection within each stratum is by random number table, so it is probability sampling.", "Cluster sampling randomly selects whole groups such as schools and tests everyone in them. Here individual teachers are drawn from sex-based lists, not intact groups."], "r": "s7"},
    {"id": "sr-06", "q": "No list of households exists for a mental health survey in a large Bengaluru slum. The area map is divided into 120 blocks, 12 blocks are chosen by lottery, and every household in them is interviewed. Which sampling method is this?", "o": ["Area sampling", "Stratified random sampling", "Systematic sampling", "Snowball sampling"], "w": ["Area sampling is cluster sampling with geographical clusters (blocks, villages), as C. R. Kothari describes. It needs only a map, not a list of people, but neighbours tend to be alike, so for equal n sampling error is usually larger than in simple random sampling.", "Stratified sampling divides the population into strata and samples from every stratum. Here 108 of the 120 blocks are never visited; whole randomly chosen blocks are studied instead.", "Systematic sampling takes every kth unit from an ordered list after a random start. Here there is no list of people and no fixed interval: blocks are drawn by lottery.", "Snowball sampling grows by referral through hidden networks and is non-probability. Here blocks are chosen by chance from a map, which is a probability method."], "r": "s7"},
    {"id": "sr-07", "q": "To pilot a new exam-anxiety scale, a researcher asks the headmaster of a Pune school to pick 20 Class 10 pupils he judges most typical of the school. She hopes they will represent all the pupils. Which sampling method is this?", "o": ["Purposive (judgmental) sampling", "Stratified random sampling", "Quota sampling", "Convenience sampling"], "w": ["Selection by someone's judgment of who is typical is purposive (judgmental) sampling; Michael Quinn Patton lists typical-case sampling among purposive strategies. However expert the judge, selection is not random, so sampling error cannot be estimated.", "Stratified random sampling would divide pupils into strata (e.g. sections or sex) and draw randomly within each from a list. Being judged typical is not a random draw, however representative it looks.", "Quota sampling fills preset numbers per subgroup, e.g. 10 boys and 10 girls. No subgroup counts are set here; the headmaster's judgment of typicality decides.", "Convenience sampling takes whoever is at hand, e.g. the first 20 pupils in the corridor. Here pupils are chosen deliberately for being typical, which is judgment, not availability."], "r": "s7"},
    {"id": "sr-08", "q": "A researcher numbers every household in an old Mysuru telephone directory and picks 400 using a random number table. Households without landlines, mostly poorer ones, could never be chosen, and the survey overestimates income. Which sampling method was used?", "o": ["Simple random sampling", "Convenience sampling", "Quota sampling", "Systematic sampling"], "w": ["Each listed household had an equal chance via a random number table, so the method is simple random sampling. The bias is non-sampling (coverage) error from a faulty frame; unlike sampling error, it does not shrink as n grows.", "Convenience sampling picks whoever is easy to reach, with no random selection. A biased result does not turn a method into non-probability sampling; here a random number table did the choosing.", "Quota sampling fills preset subgroup numbers by non-random choice. There are no quotas here, and the bias comes from the list itself, not from interviewers' choices.", "Systematic sampling would take every kth household after a random start. Drawing 400 independent numbers from a random number table is simple random, not systematic."], "r": "s7"},
    {"id": "sr-09", "q": "A survey needs 50 men and 50 women aged 18 to 25. The interviewer stands in a Bengaluru mall and approaches whoever she chooses until she has 50 of each. Which sampling method is this?", "o": ["Quota sampling", "Stratified random sampling", "Convenience sampling", "Purposive sampling"], "w": ["Preset numbers per subgroup, filled by the interviewer's own non-random choice, is quota sampling, the non-probability cousin of stratified sampling. The demographic profile looks right, but selection within each quota is biased and sampling error cannot be estimated.", "The trap: stratified random sampling also sets numbers per subgroup, but then selects randomly within each stratum from a list. Here there is no list and no random selection inside the quotas.", "Convenience sampling takes whoever is available with no control over the sample's make-up. The preset 50 and 50 targets make this quota sampling; convenience operates only inside each quota.", "Purposive sampling picks cases for a special characteristic or expertise the researcher judges important. Here any man or woman aged 18 to 25 fills a slot until the count is reached."], "r": "s7"},
    {"id": "sr-10", "q": "Of 2,000 students at a Delhi college, only 100 are from the North-East. To compare the two groups, a researcher randomly draws 50 from the North-East list and 50 from the list of the other 1,900. Which sampling method is this?", "o": ["Disproportionate stratified random sampling", "Proportionate stratified random sampling", "Quota sampling", "Simple random sampling"], "w": ["Random selection within strata at unequal fractions (50/100 = 50% vs 50/1900 ≈ 2.6%) is disproportionate stratified sampling, used to get enough cases from a small stratum; whole-college estimates must be weighted back. Jerzy Neyman (1934) showed unequal allocation can be optimal.", "Proportionate stratified sampling would use one fraction for every stratum: 5% gives 5 North-East and 95 other students. That would leave too few North-East students to analyse.", "Quota sampling also fixes 50 and 50 but fills them by non-random choice. Here each group is drawn randomly from its own list, so it stays a probability method.", "Simple random sampling of 100 from the whole list of 2,000 would yield about 5 North-East students by chance. Here the two groups are listed and sampled separately."], "r": "s7"},
    {"id": "sr-11", "q": "For a Karnataka survey of exam anxiety, a researcher randomly selects 5 districts, then 10 high schools within each chosen district, then 30 Class 10 students from each school's register. Which sampling method is this?", "o": ["Multistage sampling", "Single-stage cluster sampling", "Stratified random sampling", "Quota sampling"], "w": ["Random selection repeated at successive levels (district, school, student) is multistage sampling, cluster sampling applied in stages, with sampling error accumulating at each stage. India's National Sample Survey, set up under Prasanta Chandra Mahalanobis in 1950, uses such designs.", "Single-stage cluster sampling would randomly choose schools and test every Class 10 student in them. Here students are sampled again inside each school, adding a further stage.", "Stratified sampling would sample from every district, each treated as a stratum. Here most districts are never selected; districts drawn by chance are clusters, not strata.", "Quota sampling fixes subgroup numbers and fills them non-randomly. Every stage here uses random selection, so this is a probability method."], "r": "s7"},
    {"id": "sr-12", "q": "In a grounded theory study of help-seeking for psychosis in rural Karnataka, early interviews suggest that 'fear of neighbours knowing' delays care. So the researcher next seeks families living anonymously in Bengaluru city. Which sampling method is this?", "o": ["Theoretical sampling", "A priori purposive sampling", "Snowball sampling", "Convenience sampling"], "w": ["Choosing whom to sample next from the categories emerging in the analysis is theoretical sampling, defined by Barney Glaser and Anselm Strauss (1967). It continues until theoretical saturation, when new data add no new properties to the categories.", "Purposive sampling of information-rich cases, Michael Quinn Patton's phrase, is normally fixed from the research question before data collection. Here the choice of city families arose mid-study from the analysis, which makes it theoretical.", "Snowball sampling recruits through referrals from existing participants, for hidden groups. Here the researcher chose the next group herself, guided by an emerging category, not by whom participants knew.", "Convenience sampling takes whoever is easiest to reach. Moving to city families was harder, and was done deliberately to test the 'fear of neighbours knowing' category."], "r": "s24"}
  ]},
  {k: "eh", name: "Error Hunt", icon: "🚨", sub: "Type I vs Type II, power, p values and the null hypothesis traps", n: "type I error", qs: [
    {"id": "eh-01", "q": "A new anti-anxiety drug in fact has no effect at all. A trial nevertheless finds p = .03, and the authors conclude that the drug works. What has happened?", "o": ["A Type I error (false positive)", "A Type II error (false negative)", "A correct rejection of H₀", "A correct retention of H₀"], "w": ["Rejecting a true H₀ is a Type I error, a false positive; its probability is α, fixed in advance (usually .05). The Type I and Type II framework comes from Jerzy Neyman and Egon Pearson.", "A Type II error (β) is the opposite mistake: retaining a false H₀ and missing an effect that is really there. It would be right if the drug truly worked but the trial found p > .05.", "Rejecting H₀ is correct only when H₀ is false; the probability of doing so is power (1 − β). It would be right if the drug really did reduce anxiety.", "Correct retention needs a non-significant result while H₀ is true. It would be right if the trial had found p > .05 for this ineffective drug."], "r": "s8"},
    {"id": "eh-02", "q": "A drug truly reduces relapse in schizophrenia, but a small trial with 20 patients finds p = .21 and reports no significant difference. What has happened?", "o": ["A Type II error", "A Type I error", "H₀ has been proved true", "A correct decision, with probability 1 − β"], "w": ["Failing to reject a false H₀ is a Type II error, a false negative, with probability β. Small samples are the usual cause: with 20 patients power is low, so a real effect is easily missed.", "A Type I error is rejecting a true H₀ (false positive). It would be right if the drug did nothing yet the trial found p < .05.", "No significance test proves H₀. p = .21 only means the data were not surprising enough under H₀ to reject it; the researcher 'fails to reject' H₀, and here the drug does in fact work.", "1 − β is power, the probability of correctly rejecting a false H₀. It would describe the outcome if this trial had found p < .05 for the working drug."], "r": "s8"},
    {"id": "eh-03", "q": "Before collecting data, a researcher studying ECT and memory sets α = .01 instead of the usual .05, because a false claim of harm would be costly. What does α = .01 tell you?", "o": ["A 1% risk of rejecting a true H₀", "A 1% chance that H₀ is true", "The study's power is .99", "A 1% chance of a Type II error"], "w": ["α is the probability of a Type I error, rejecting H₀ when it is true, and the researcher fixes it in advance. Ronald Fisher popularised .05; .01 is chosen when a false positive would be costly.", "α is computed assuming H₀ is true, so it cannot be the probability that H₀ is true. That reverse probability would need Thomas Bayes's theorem and a prior, which significance testing does not use.", "Power is 1 − β, not 1 − α. 1 − α (.99) is the probability of correctly retaining a true H₀. Power depends on n, effect size and α, and a stricter α lowers it.", "β, the Type II error rate, is not set directly; it follows from α, n, effect size and variability. Tightening α to .01 actually raises β."], "r": "s8"},
    {"id": "eh-04", "q": "An M.Phil student's thesis plan has a power of only .45 to detect a medium effect. Which single change most directly raises power without increasing the Type I error rate?", "o": ["Increase the sample size", "Change α from .05 to .01", "Use a two-tailed test, not one-tailed", "Switch to a non-parametric test"], "w": ["Power (1 − β) is the chance of detecting a real effect. A larger n shrinks the standard error, so the H₀ and H₁ sampling distributions overlap less, and α stays put. Jacob Cohen set .80 as the usual target.", "Moving α from .05 to .01 shrinks the rejection region, which lowers power and raises β. It would be right if the aim were fewer false positives.", "A two-tailed test splits α between both tails, so the critical value moves further out (z of 1.96 instead of 1.645 at .05) and power falls. One-tailed is more powerful when the predicted direction is correct.", "When parametric assumptions hold, rank tests are slightly less powerful because ranking discards information. Switching makes sense only when the data violate those assumptions."], "r": "s8"},
    {"id": "eh-05", "q": "A paper reports p = .04 for a yoga intervention for anxiety. A classmate says, 'So there is only a 4% chance that the null hypothesis is true.' What does p = .04 actually mean?", "o": ["4% chance of such data if H₀ true", "4% chance that H₀ is true", "96% chance the effect is real", "96% chance the result will replicate"], "w": ["p is the probability of a result at least this extreme assuming H₀ is true, P(data | H₀); Ronald Fisher used it as a measure of surprise. Since .04 < .05, H₀ is rejected, but p is not the probability of H₀ itself.", "This reverses the conditional: P(H₀ | data) is not P(data | H₀). The probability of H₀ itself would need Thomas Bayes's theorem and a prior, which significance testing does not use.", "The same reversal from the other side: 1 − p is not the probability that H₁ is true. A significant p from a small study or an implausible hypothesis can still be a false positive.", "p is not a replication probability. Even a real effect, retested with the same n, can easily give p > .05, especially when power is modest."], "r": "s8"},
    {"id": "eh-06", "q": "Before the study, a researcher predicts on theoretical grounds that mindfulness training will lower exam anxiety (not merely change it). Using a z test at α = .05, where is the critical region?", "o": ["z ≤ −1.645 (lower tail only)", "z ≤ −1.96 or z ≥ +1.96", "z ≤ −1.96 (lower tail only)", "z ≤ −2.58 or z ≥ +2.58"], "w": ["A directional H₁ (trained mean lower than control) puts the whole α = .05 in the predicted tail, so H₀ is rejected if z ≤ −1.645. The direction must be fixed before the data, on theoretical grounds.", "±1.96 (2.5% in each tail) is the critical region for a non-directional H₁ such as 'mindfulness will change anxiety'. It would be right if no direction had been predicted.", "−1.96 cuts off only 2.5% of the lower tail, so using it alone would make this a one-tailed test at α = .025, not .05. 1.96 belongs with a two-tailed test at .05.", "±2.58 is the two-tailed critical z at α = .01 (0.5% in each tail). It would be right for a non-directional test at the stricter .01 level."], "r": "s8"},
    {"id": "eh-07", "q": "A trial of 16 patients finds group therapy lowered loneliness scores by 4 points, but p = .09. The discussion says, 'Group therapy has no effect on loneliness.' Which statement correctly fixes this?", "o": ["H₀ not rejected; study may lack power", "H₀ was accepted, so therapy has no effect", "H₀ was proved true at the .05 level", "A Type I error was made"], "w": ["A non-significant result means the evidence was too weak to reject H₀, not that H₀ is true: absence of evidence is not evidence of absence. With 16 patients power is low, so a real 4-point effect may have been missed (a Type II error).", "'Accepting' H₀ turns a failure to find evidence into proof of no effect. The correct language, from Ronald Fisher's framework, is 'failed to reject' or 'retained' H₀; the effect could be real but undetected.", "Significance tests never prove H₀ (or H₁). α = .05 limits only the risk of a false positive; it gives no guarantee that a non-significant result reflects a true null.", "A Type I error needs H₀ to be rejected, and here it was not. If the therapy really works, the possible error is Type II, a missed effect."], "r": "s8"},
    {"id": "eh-08", "q": "A trial of 4,000 patients (2,000 per arm) finds a new antidepressant lowers HAM-D scores by 1 point more than placebo, p < .001. The pooled SD is 8. What is the best conclusion?", "o": ["Significant, but a trivial effect (d = 0.125)", "A large effect, because p < .001", "A 99.9% chance the drug works", "Invalid, because the sample is too large"], "w": ["Significance shows how surprising the data are under H₀, and huge samples make tiny effects significant. Jacob Cohen's d = (M₁ − M₂)/SD = 1/8 = 0.125, below his 'small' benchmark of 0.2, so the benefit is clinically trivial.", "p is not a measure of effect size. A very small p with 4,000 patients mostly reflects the large n; size is read from d, using Jacob Cohen's benchmarks of 0.2 small, 0.5 medium and 0.8 large.", "p is the probability of such data if H₀ were true, not the probability that the drug works. 1 − p is not the probability that H₁ is true.", "A large sample is not a flaw: it gives high power and a precise estimate. The fault is in interpretation; report the effect size and a confidence interval alongside p."], "r": "s8"},
    {"id": "eh-09", "q": "A thesis compares two groups on 10 different outcome measures using 10 independent t tests, each at α = .05. Suppose no real differences exist anywhere. Roughly what is the chance of at least one false positive?", "o": ["About .40", "Exactly .05", "About .50 (10 × .05)", "About .005"], "w": ["Each test has a .95 chance of no false positive, so the familywise error rate is 1 − (.95)¹⁰ ≈ .40. Multiple testing inflates Type I error, which is why corrections such as Carlo Emilio Bonferroni's exist.", ".05 is the per-comparison α, the risk for one test on its own. It would be right if only a single test were run; across ten tests the familywise risk is far larger.", "Adding 10 × .05 overstates the risk because the events overlap; the sum is only an upper bound. For independent tests the exact value is 1 − (.95)¹⁰ ≈ .40.", ".005 is the per-test α under Carlo Emilio Bonferroni's correction (.05/10), the threshold each test should meet to hold the familywise rate near .05. It is the fix, not the inflated risk."], "r": "s8"},
    {"id": "eh-10", "q": "After a significant one-way ANOVA comparing four therapy groups, a researcher runs every pairwise comparison with a Bonferroni correction, keeping the familywise α at .05. What α should each comparison use?", "o": ["α = .05/6 ≈ .008", "α = .05/4 = .0125", "α = .05 for each test", "α = .05 × 6 = .30"], "w": ["Four groups give 4 × 3/2 = 6 pairwise comparisons. Carlo Emilio Bonferroni's correction divides the familywise α by the number of comparisons, .05/6 ≈ .008, keeping the overall Type I risk at or below .05 at some cost to power.", "Dividing by 4 counts the groups, not the comparisons. With k groups there are k(k − 1)/2 pairs; .05/4 would be right only if exactly four comparisons were planned.", "Leaving α at .05 for each test lets the familywise error climb to about 1 − (.95)⁶ ≈ .26. An uncorrected α is acceptable for a single planned comparison.", "Multiplying α makes each test more lenient, the opposite of a correction. Carlo Emilio Bonferroni's method can also be applied by multiplying each p value by 6 and comparing it with .05, which is the same as using .05/6."], "r": "s10"},
    {"id": "eh-11", "q": "Keeping the same sample size and the same true effect, a researcher tightens α from .05 to .01. What happens?", "o": ["Type I risk falls, β rises, power falls", "Both Type I and Type II errors fall", "Power rises, because the test is stricter", "β stays the same; only α changes"], "w": ["At fixed n and effect size, α and β trade off: a smaller α shrinks the rejection region, so fewer false positives but more misses (β up, power down). Only a larger n, larger effect or less error variance lowers both.", "Both errors fall together only when the standard error shrinks, usually by increasing n. Changing α alone just moves the critical value and trades one error for the other.", "Stricter is not more powerful. With a smaller rejection region a real effect must be larger to cross the critical value, so power drops; Jacob Cohen's power tables show this at every n.", "β is not set directly; it depends on α, n, effect size and variability. Moving the critical z from 1.96 to 2.58 (two-tailed) increases β."], "r": "s8"},
    {"id": "eh-12", "q": "A researcher pre-registers a one-tailed test (α = .05) predicting that a new therapy will LOWER anxiety. Instead, the therapy group's anxiety comes out much HIGHER than control, z = +2.40. What is the correct conclusion?", "o": ["Retain H₀: z is in the unpredicted tail", "Reject H₀: z exceeds 1.96", "Reject H₀: z exceeds 1.645", "Switch to two-tailed, then reject H₀"], "w": ["With a directional H₁ the whole critical region lies in the predicted lower tail, z ≤ −1.645. A large effect in the opposite direction cannot be declared significant, so H₀ is retained. This is the price of a one-tailed test's extra power.", "1.96 is the two-tailed critical value at .05. It would apply, and z = +2.40 would be significant, if the hypothesis had been non-directional from the start.", "+1.645 is the cut-off for a one-tailed test predicting an increase. It would be right only if the researcher had predicted that therapy raises anxiety.", "Changing the tail after seeing the data is a form of p-hacking and inflates the Type I error rate. The direction, and so the tail, must be fixed before data collection."], "r": "s8"}
  ]},
  {k: "nc", name: "Normal Curve Boss", icon: "🔔", sub: "The final boss: 18 normal curve questions plus your weakest one from each game", n: "normal curve", boss: true, pass: 0.8, qs: [
    {"id": "nc-01", "q": "Which of these is NOT a property of the normal probability curve?", "o": ["Its tails touch the baseline at ±3σ", "Its points of inflection lie at ±1σ", "Its mean, median and mode coincide", "The total area under it equals 1"], "w": ["The curve of Abraham de Moivre and Carl Friedrich Gauss is asymptotic: the tails come ever closer to the baseline but never touch it. About 0.13% of cases still lie beyond +3σ, and the same beyond −3σ.", "A true property: the curve changes from concave-down to concave-up exactly one SD either side of the mean. It would be the answer only if the item asked which statement IS a property.", "A true property: a symmetrical, unimodal curve puts mean, median and mode at the same centre point. The three separate only when a distribution is skewed, which the normal curve never is.", "A true property: the total area is 1.00 (100% of cases), so areas read as probabilities. It, like β₂ = 3 (mesokurtic), would be a correct pick in a 'which IS true' version."], "r": "s6"},
    {"id": "nc-02", "q": "Scores on a depression inventory used in a Bangalore clinic are normally distributed. What percentage of patients score between the mean and 1 SD above the mean?", "o": ["34.13%", "68.26%", "13.59%", "15.87%"], "w": ["On the normal curve of Carl Friedrich Gauss, the area from the mean to +1σ is 34.13% of cases. By symmetry the same 34.13% lies between the mean and −1σ.", "68.26% is the area within ±1σ, both sides of the mean together. It would be right if the item asked for patients between 1 SD below and 1 SD above the mean.", "13.59% is the slice between +1σ and +2σ. It would be right for patients scoring between 1 and 2 SDs above the mean.", "15.87% is the tail above +1σ (50 − 34.13). It would be right if the item asked what percentage score more than 1 SD above the mean."], "r": "s6"},
    {"id": "nc-03", "q": "On an anxiety scale the norm group's mean is 40 and SD is 8. A patient scores 28. What is the patient's T score?", "o": ["35", "65", "48.5", "77.5"], "w": ["First z = (28 − 40)/8 = −1.5. William McCall's T score is T = 50 + 10z = 50 − 15 = 35, so the patient sits 1.5 SD below the norm mean.", "65 drops the minus sign: the patient is below the mean, so T must be under 50. 65 would be right for a raw score of 52, which is z = +1.5.", "48.5 adds z straight to 50 without multiplying by the T scale's SD of 10. It would fit only a scale with mean 50 and SD 1.", "77.5 is 100 + 15z, the Wechsler deviation IQ for z = −1.5. It would be right if the item asked for an IQ-type score, not a T score."], "r": "s6"},
    {"id": "nc-04", "q": "Ravi got 65% marks in a college entrance test, and his percentile rank is 90. What does the 90 tell you?", "o": ["About 90% of candidates scored below him", "He answered 90% of the items correctly", "Only 10% of candidates scored below him", "One of the two figures must be wrong"], "w": ["A percentile rank is a position in the group: the percentage of candidates scoring below Ravi. His 65% is a percentage of marks, a different thing.", "That describes a percentage score, which for Ravi is 65%. It would be right only if the item asked about his marks rather than his rank in the group.", "This reverses the rank: 10% below him is a percentile rank of 10. It would be right if he were near the bottom of the group, not in the top 10%.", "Percentage and percentile need not match: on a hard test 65% marks can beat 90% of candidates. The two coincide only by chance."], "r": "s6"},
    {"id": "nc-05", "q": "Meera's IQ on the Stanford-Binet Form L-M (mean 100, SD 16) is 116. Assuming a normal distribution, what is her approximate percentile rank?", "o": ["84th", "86th", "68th", "34th"], "w": ["z = (116 − 100)/16 = +1. The area below z = +1 is 50 + 34.13 = 84.13%, so about the 84th percentile. Lewis Terman and Maud Merrill's Form L-M used SD 16; the Wechsler scales use 15.", "86th comes from using the Wechsler SD of 15: z = 16/15 ≈ 1.07. It would be right for an IQ of 116 on the WAIS or WISC, not on Form L-M.", "68 comes from the 68.26% within ±1σ, which is an area, not a percentile. The 68th percentile would need a z of only about +0.47.", "34 is the 34.13% between the mean and +1σ, forgetting the 50% below the mean. The 34th percentile is actually below average, about z = −0.41."], "r": "s6"},
    {"id": "nc-06", "q": "Anita scored 65 in Psychology (class mean 55, SD 5) and 80 in Statistics (class mean 70, SD 10). Relative to her class, in which paper did she do better?", "o": ["Psychology: z = +2 vs +1", "Statistics: higher raw score", "Equal: both are 10 above the mean", "Cannot compare different tests"], "w": ["z scores put different tests on one scale: Psychology z = (65 − 55)/5 = +2, Statistics z = (80 − 70)/10 = +1. She beat about 97.7% of the class in Psychology but only about 84% in Statistics.", "Raw scores from different tests are not comparable when their means and SDs differ. A raw comparison would work only if both papers had the same mean and SD.", "Both are 10 marks above the mean, but 10 marks is two SDs in Psychology and one in Statistics. Equal deviations mean equal standing only when the SDs are equal.", "Comparing across tests is exactly what standard scores are for. Comparison would be impossible only if a paper's mean or SD were unknown."], "r": "s6"},
    {"id": "nc-07", "q": "On the WISC (mean 100, SD 15), what percentage of children are expected to score between IQ 115 and IQ 130?", "o": ["13.59%", "34.13%", "2.14%", "27.18%"], "w": ["IQ 115 is z = +1 and IQ 130 is z = +2 on David Wechsler's scale. The normal curve area between +1σ and +2σ is 47.72 − 34.13 = 13.59%.", "34.13% is the area between the mean and +1σ, that is IQ 100 to 115. It would be right if the band started at the mean.", "2.14% is the slice between +2σ and +3σ, IQ 130 to 145. It would be right one band further out.", "27.18% doubles 13.59, counting IQ 70 to 85 as well as 115 to 130. It would be right if the item asked for children 1 to 2 SDs from the mean in either direction."], "r": "s6"},
    {"id": "nc-08", "q": "A Bangalore school board reports results in stanines. What percentage of students is expected to fall in stanines 4, 5 and 6 combined?", "o": ["54%", "68%", "33%", "20%"], "w": ["Stanines (mean 5, SD about 2) cut the normal curve into half-SD bands (the two ends open) holding 4, 7, 12, 17, 20, 17, 12, 7 and 4 percent. Stanines 4 to 6 give 17 + 20 + 17 = 54%, from −0.75σ to +0.75σ.", "68% (68.26) is the area within ±1σ. Stanines 4 to 6 span only ±0.75σ, so they hold less; 68% would be right for z = −1 to +1.", "33% treats the nine stanines as equal ninths (3 of 9). That would be right for equal-frequency bands, but the inner stanines are equal in width (half an SD), so the middle ones hold more cases.", "20% is stanine 5 alone, the single largest band. It would be right if the item asked only about stanine 5."], "r": "s6"},
    {"id": "nc-09", "q": "In an MA entrance mock test the mean is 42, the median 45 and the mode 51. What is the shape of the score distribution?", "o": ["Negatively skewed", "Positively skewed", "Symmetrical", "Cannot tell without the SD"], "w": ["Mean < median < mode: a few very low scores drag the mean left, giving a long left tail. Skew is named for the tail, and the mean always sits furthest into it, as on a very easy test with a ceiling.", "Positive skew shows the reverse order, mode < median < mean, as on a very hard test where most score low. It would be right if the mean were the largest of the three.", "A symmetrical (normal) curve has mean, median and mode equal. It would be right only if all three were equal; a 9-point gap between mean and mode rules it out.", "The SD is needed for the size of the skew, as in Karl Pearson's coefficient, not its direction. The order of mean, median and mode alone gives the direction."], "r": "s5"},
    {"id": "nc-10", "q": "Symptom checklist scores of 50 ward patients have mean 52, median 49 and SD 6. What is Karl Pearson's coefficient of skewness?", "o": ["+1.5", "+0.5", "−1.5", "+0.25"], "w": ["Karl Pearson's second coefficient: Sk = 3(Mean − Median)/SD = 3(52 − 49)/6 = +1.5. It is positive because the mean lies above the median, so the long tail points to high symptom scores.", "+0.5 drops the 3: (52 − 49)/6. That is Pearson's first coefficient, (Mean − Mode)/SD, and would be right if 49 were the mode rather than the median.", "−1.5 reverses the subtraction (Median − Mean). A negative coefficient would be right only if the mean fell below the median.", "+0.25 divides by the variance (36) instead of the SD (6). It would be right only if the SD itself were 36."], "r": "s5"},
    {"id": "nc-11", "q": "Two batches of students have the same mean and SD on a memory test. Batch A's kurtosis (β₂) is 4.2 and Batch B's is 1.8. How are the two distributions described?", "o": ["A leptokurtic, B platykurtic", "A platykurtic, B leptokurtic", "Both mesokurtic, as the SDs match", "A positively, B negatively skewed"], "w": ["Karl Pearson named the shapes: β₂ = 3 is mesokurtic (normal), above 3 leptokurtic (tall, thin peak, heavy tails), below 3 platykurtic (flat). So A at 4.2 is leptokurtic and B at 1.8 platykurtic.", "This reverses the rule: a large β₂ means a sharp peak, a small one a flat top. It would be right if A's β₂ were below 3 and B's above 3.", "Equal means and SDs do not fix the shape: kurtosis is the fourth moment, separate from the second (variance). Both would be mesokurtic only if each β₂ were 3.", "β₂ measures peakedness, not asymmetry. Skew would need the third moment or the order of mean, median and mode, which this item does not give."], "r": "s5"},
    {"id": "nc-12", "q": "A screening inventory at a psychiatric OPD reports T scores. The clinic wants to flag the top 5% of patients for a detailed interview. Which T score is the cutoff?", "o": ["About 66.45", "About 69.6", "About 75.8", "60"], "w": ["The top 5% is a one-tailed area, so z = 1.645. On William McCall's T scale (mean 50, SD 10), T = 50 + 10(1.645) = 66.45.", "69.6 uses z = 1.96, which cuts off 2.5% in one tail (5% split over both tails). It would be right for flagging the top 2.5%.", "75.8 uses z = 2.58, the two-tailed 1% value, which leaves 0.5% in each tail. It would be right for flagging the top 0.5%.", "T 60 is z = +1, which flags the 15.87% above +1σ. It would be right for flagging roughly the top 16%."], "r": "s6"},
    {"id": "nc-13", "q": "A normally distributed aptitude test has mean 80 and SD 20. Between which two scores does the middle 50% of candidates lie?", "o": ["About 66.5 and 93.5", "60 and 100", "70 and 90", "40 and 120"], "w": ["In a normal curve Q1 and Q3 lie 0.6745σ from the mean, so the quartile deviation Q, also called the probable error, is 0.6745 × 20 ≈ 13.5. The middle 50% runs from 80 − 13.5 to 80 + 13.5.", "60 to 100 is ±1σ, which holds 68.26% of cases, not 50%. It would be right if the item asked for the middle 68%.", "70 to 90 is ±0.5σ, which holds only about 38% of cases. It would be right if the item asked for the middle 38% or so.", "40 to 120 is ±2σ, which holds 95.44% of cases. It would be right for the middle 95% or so (strictly ±1.96σ for exactly 95%)."], "r": "s6"},
    {"id": "nc-14", "q": "Symptom-count scores in a community sample are strongly positively skewed. A researcher converts every score to a z score. What will the distribution of z scores look like?", "o": ["Still positively skewed, mean 0, SD 1", "Normal, mean 0, SD 1", "Symmetrical, mean 0, original SD", "Negatively skewed, mean 0, SD 1"], "w": ["z = (X − M)/SD is a linear transformation: it shifts and rescales every score but keeps the shape, so the skew stays. It standardises (mean 0, SD 1); it does not normalise.", "A normal shape needs a normalised (area) transformation through percentile ranks, as in normalised T scores or stanines. This would be right if those, not linear z scores, were computed.", "Mean 0 with the original SD describes deviation scores (X − M), not z scores, which always have SD 1. Even deviation scores would be symmetrical only if the raw scores were.", "Dividing by a positive SD cannot flip the direction of skew. Negative skew would appear only if the scores were reflected, for example subtracted from the maximum."], "r": "s6"},
    {"id": "nc-15", "q": "On a normally distributed reading test, Asha moves from the 50th to the 60th percentile and Ravi from the 85th to the 95th. Whose underlying score improved more?", "o": ["Ravi's: about 0.61 SD vs 0.25 SD", "Equal: 10 percentile points each", "Asha's: raw gaps are widest at the centre", "Cannot say without the raw SD"], "w": ["Percentiles are ordinal: cases crowd the middle, so percentiles are squeezed at the centre and stretched in the tails. In z terms Asha moves 0 to 0.25, while Ravi moves 1.04 to 1.64, about 0.61 SD.", "Equal percentile steps are not equal score steps, so percentiles cannot be subtracted like interval data. Equal gains would be right only for a rectangular (uniform) distribution.", "This reverses the rule: near the centre many cases sit in a narrow raw-score range, so 10 percentile points there is a small raw change. It would hold only for a U-shaped distribution, thin in the middle.", "The SD only turns SD units into raw marks; the ordering is fixed by the normal curve whatever the SD. The SD would be needed only to state the gains in marks."], "r": "s6"},
    {"id": "nc-16", "q": "A memory test has population SD 12. Many random samples of 64 patients are drawn. Within what distance of the population mean should 95% of the sample means fall?", "o": ["±2.94", "±23.52", "±1.5", "±0.37"], "w": ["The standard error of the mean is σ/√N = 12/√64 = 1.5. By the central limit theorem sample means are approximately normal, so 95% lie within ±1.96 SE = ±2.94.", "±23.52 is 1.96 × 12, using the SD of individual scores. It would be right for where 95% of single patients' scores fall, not sample means.", "±1.5 is one standard error, which covers only about 68.26% of sample means. It would be right if the item asked for roughly two thirds of them.", "±0.37 is 1.96 × 12/64: it divides σ by N instead of √N. That figure would be right only for samples of 4,096, whose square root is 64."], "r": "s7"},
    {"id": "nc-17", "q": "Reaction times in a population of patients are strongly positively skewed, with SD σ. Thousands of random samples of N = 100 are drawn and their means plotted. Which description fits this distribution of means?", "o": ["Nearly normal, SD = σ/√N", "Positively skewed, SD = σ/√N", "Nearly normal, SD = σ", "Nearly normal, SD = σ/N"], "w": ["The central limit theorem (Pierre-Simon Laplace): with large N the sampling distribution of the mean approaches normal whatever the population's shape, centred on μ, with SD equal to the standard error σ/√N, here σ/10.", "Means of large samples lose the population's skew. Clear skew would survive only with small samples (below the usual rule of thumb of N = 30) from this skewed population.", "σ is the spread of single reaction times; means vary far less than single scores. SD = σ would be right only for N = 1, that is, for the raw scores themselves.", "σ²/N is the variance of the sampling distribution; its SD is the square root, σ/√N. Dividing σ itself by N (σ/100) makes the spread ten times too small."], "r": "s7"},
    {"id": "nc-18", "q": "A client has a sten of 7 on Raymond Cattell's 16PF and a stanine of 7 on an aptitude test. Which score shows the higher relative standing?", "o": ["Stanine 7: z = +1 vs +0.75", "Equal: both are 7, with SD 2", "Sten 7: z = +1 vs +0.75", "Cannot compare across scales"], "w": ["Convert both through z. Sten (standard ten, mean 5.5, SD 2): (7 − 5.5)/2 = +0.75. Stanine (mean 5, SD about 2): (7 − 5)/2 = +1. So the stanine is higher, about the 84th vs the 77th percentile.", "The same number means different things when the means differ (5.5 vs 5). Equal numbers would mean equal standing only if both scales had the same mean and SD.", "This swaps the means: 5 belongs to the stanine and 5.5 to the sten. It would be right only if the sten mean were 5 and the stanine mean 5.5.", "Different standard-score scales become comparable once each is converted to z. Comparison would fail only if a scale's mean or SD were unknown."], "r": "s6"}
  ]}
]};
